#include <iostream>
// These headers will be automatically generated by Verilator
#include "Vmandelbrot.h"
#include "verilated.h"
#include "verilated_vcd_c.h"

int main(int argc, char** argv) {
    // 1. Initialize the Verilator simulation environment
    Verilated::commandArgs(argc, argv);
    Verilated::traceEverOn(true);

    // 2. Instantiate the Verilog module (Device Under Test)
    Vmandelbrot* dut = new Vmandelbrot;

    // 3. Set up the VCD waveform tracing
    VerilatedVcdC* m_trace = new VerilatedVcdC;
    dut->trace(m_trace, 99); // Trace down to 99 levels of hierarchy
    m_trace->open("build/waveform.vcd");

    // 4. Simulation parameters
    // 4. Simulation parameters
    vluint64_t sim_time = 0;
    const vluint64_t CLK_HALF_PERIOD = 6734;
    // We want to simulate ~1.1 seconds. 
    // 1.1 seconds = 1.1 trillion picoseconds (1,100,000,000,000)
    const vluint64_t MAX_SIM_TIME = 2 * 750 * 1650 * 13468ULL;

    std::cout << "Starting 27 MHz simulation..." << std::endl;

    // 5. The core simulation loop
    while (sim_time < MAX_SIM_TIME && !Verilated::gotFinish()) {
        dut->clk_pixel ^= 1;
        dut->eval();
        m_trace->dump(sim_time);

        // Advance time by half a 27 MHz clock cycle (18,518 picoseconds)
        sim_time += CLK_HALF_PERIOD;
    }
    std::cout << "Simulation complete. Waveform saved to build/waveform.vcd" << std::endl;

    // 6. Clean up memory
    m_trace->close();
    delete dut;
    delete m_trace;

    return 0;
}